"""Reproduce the exact preserved flat reflection coordinate diagram."""
from pathlib import Path
svg_bytes = b'<svg xmlns="http://www.w3.org/2000/svg" width="760" height="650" viewBox="0 0 760 650" role="img" aria-labelledby="title desc">\r\n<title id="title">A reflected wave has two full covectors and one compressed boundary limit</title>\r\n<desc id="desc">Exact section tau equals one of the flat wave symbol rho squared minus tau squared. The base rays are t equals minus r incoming, and t equals r outgoing. The compressed normal components are zeta equals r and zeta equals minus r, both meeting at r equals zero, zeta equals zero.</desc>\r\n<defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="context-stroke"/></marker></defs>\r\n<rect width="760" height="650" rx="12" fill="#f8fafb"/>\r\n<g font-family="Arial,sans-serif" font-size="18" fill="#243e4b">\r\n<text x="34" y="36" font-size="22" font-weight="bold">Two transverse wave branches, \xcf\x84 = 1</text>\r\n<text x="34" y="66">Base projection for P = D\xe1\xb5\xa3\xc2\xb2 \xe2\x88\x92 D\xe2\x82\x9c\xc2\xb2; r \xe2\x89\xa5 0</text>\r\n<path d="M96 320H672" stroke="#687882" stroke-width="1.5" marker-end="url(#arrow)"/>\r\n<path d="M380 337V91" stroke="#687882" stroke-width="1.5" marker-end="url(#arrow)"/>\r\n<text x="684" y="326">t</text><text x="392" y="102">r</text>\r\n<text x="127" y="350">\xe2\x88\x921</text><text x="373" y="350">0</text><text x="614" y="350">1</text>\r\n<text x="358" y="207">1</text>\r\n<path d="M140 200L380 320" stroke="#256783" stroke-width="4"/>\r\n<path d="M380 320L620 200" stroke="#b15536" stroke-width="4"/>\r\n<path d="M224 242L260 260" stroke="#256783" stroke-width="3" marker-end="url(#arrow)"/>\r\n<path d="M488 266L524 248" stroke="#b15536" stroke-width="3" marker-end="url(#arrow)"/>\r\n<circle cx="380" cy="320" r="6" fill="#243e4b"/>\r\n<text x="52" y="106" fill="#256783">Incoming: t = \xe2\x88\x92r</text>\r\n<text x="45" y="145" fill="#256783">\xce\xbe = dt + dr; \xcf\x81 = 1</text>\r\n<text x="488" y="106" fill="#b15536">Outgoing: t = r</text>\r\n<text x="488" y="145" fill="#b15536">\xce\xbe = dt \xe2\x88\x92 dr; \xcf\x81 = \xe2\x88\x921</text>\r\n<text x="45" y="268">Dirichlet cancellation</text>\r\n<text x="45" y="291">(r, t) = (0, 0)</text>\r\n<text x="34" y="390" font-size="22" font-weight="bold">Compressed normal component \xce\xb6 = r\xcf\x81</text>\r\n<text x="34" y="419">Tangential component \xcf\x84 stays equal to one</text>\r\n<path d="M115 535H672" stroke="#687882" stroke-width="1.5" marker-end="url(#arrow)"/>\r\n<path d="M140 624V441" stroke="#687882" stroke-width="1.5" marker-end="url(#arrow)"/>\r\n<text x="684" y="542">r</text><text x="114" y="449">\xce\xb6</text>\r\n<path d="M140 535L620 465" stroke="#256783" stroke-width="4"/>\r\n<path d="M140 535L620 605" stroke="#b15536" stroke-width="4"/>\r\n<circle cx="140" cy="535" r="6" fill="#243e4b"/>\r\n<text x="156" y="490">Same boundary covector</text>\r\n<text x="405" y="475" fill="#256783">\xcf\x81 = 1; \xce\xb6 = r</text>\r\n<text x="405" y="598" fill="#b15536">\xcf\x81 = \xe2\x88\x921; \xce\xb6 = \xe2\x88\x92r</text>\r\n<text x="108" y="474">1</text><text x="94" y="608">\xe2\x88\x921</text>\r\n<text x="613" y="560">1</text><text x="121" y="560">0</text>\r\n</g></svg>'
Path(__file__).with_name('boundary-reflection-geometry.svg').write_bytes(svg_bytes)
